<style>
  footer {
    background-color: #101C2A;
    padding: 100px 0 0;
    .footer-container {
      display: flex;
      justify-content: flex-start;
      gap: 65px; 
      margin-bottom: 120px;
      .footer-info {
        margin-right: auto;
        .footer-title {
          margin-left: 20px;
          position: relative;
          font-style: normal;
          font-weight: 400;
          font-size: 18px;
          line-height: 140%;
          color: #B9C1CA;
          &::before {
            position: absolute;
            left: -20px;
            top: 50%;
            transform: translateY(-50%);
            content: '';
            border-radius: 50%;
            display: block;
            width: 8px;
            height: 8px;
            background-color: #B9C1CA;
          }

          &::after {
            position: absolute;
            left: -20px;
            top: 50%;
            transform: translateY(-50%);
            transform-origin: center;
            animation: titleDotPop 1.6s cubic-bezier(0.16, 1, 0.3, 1) infinite;
            content: '';
            border-radius: 50%;
            display: block;
            width: 8px;
            height: 8px;
            background-color: #B9C1CA;
          }
        }
        .footer-description {
          max-width: 400px;
          font-style: normal;
          font-weight: 600;
          font-size: 48px;
          line-height: 60px;
          color: #FFFFFF;
          margin: 16px 0 68px;
        }
        .btn {
          margin: 0px auto 0 0;
          .button-icon {
            transform: translateY(-50%) rotate(-45deg);
          }
        }
      }
      .footer-nav-list {
        width: 200px;
        list-style: none;
        .footer-nav-list-item {
          .footer-list-title {
            margin-bottom: 20px;
            font-style: normal;
            font-weight: 400;
            font-size: 20px;
            line-height: 140%;
            color: #B9C1CA;
          }
          a {
            display: block;
            margin-bottom: 16px;
            text-decoration: none;
            font-style: normal;
            font-weight: 500;
            font-size: 20px;
            line-height: 140%;
            color: #FFFFFF;
          }
        }
      }
      .footer-social-list {
        display: flex;
        flex-direction: column;
        list-style: none;
        .footer-social-list-item {
          .footer-list-title {
            width: 248px;
            font-style: normal;
            font-weight: 400;
            font-size: 20px;
            line-height: 140%;
            color: #B9C1CA;
            margin-bottom: 20px;
          }
          a {
            display: block;
            margin: 0 0 16px 0;
            text-decoration: none;
            font-style: normal;
            font-weight: 500;
            font-size: 20px;
            line-height: 140%;
            color: #FFFFFF;
            svg {
              vertical-align: middle;
              margin-right: 12px;
            }
          }
        }
        .footer-social-list-item-up {
          margin-top: auto;
        }
      }
    }
  }
  .footer-all-rights {
    border-top: 1px solid #2A3E53;
    background-color: #101C2A;
    padding: 20px 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    .all-rights-text {
      font-style: normal;
      font-weight: 400;
      font-size: 18px;
      line-height: 140%;
      color: #B9C1CA;
    }
  }

  @keyframes titleDotPop {
    0% {
      transform: translateY(-50%) scale(1);
      opacity: 0.7;
    }

    70%,
    100% {
      transform: translateY(-50%) scale(2.6);
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .footer-title::after {
      animation: none;
    }
  }

  @media (max-width: 768px) {
     footer {
      background-color: #101C2A;
      padding: 56px 0 16px;
      .footer-container {
        flex-wrap: wrap;
        gap: 56px; 
